head.script:
//
                        var mensagem;
                        var initMensagem = function() {
                                mensagem = new Mensagem();
                        }
                        YAHOO.util.Event.addListener(window,'load', initMensagem);

                        function show_carregando(){
                if (document.getElementById("container") !== null){
                    document.getElementById("linkTopo").click();
                                        document.getElementById("aviso_na_tela").style.display='block';
                                        document.getElementById("aviso_na_tela").style.height= document.getElementById("container").clientHeight + 'px';
                                        document.getElementById("loading").style.display='block';
                                }
                        }


                        function hidde_carregando(){    
                                document.getElementById("aviso_na_tela").style.display='none';
                                document.getElementById("loading").style.display='none';

                        }

                        function carregarTimeout() {
                                var xhttp = new XMLHttpRequest();
                                xhttp.open("GET", "/sigeduc/sistemaTimeout", true);
                                xhttp.send();
                        }

                        window.addEventListener('load', () => {
                                // Seleciona todos os elementos <a> dentro de <li> que estão dentro da div com id 'menu-principal'
                                let linksMenu = retornaLinksMenu();

                                function addClickEventLinkMenu(linksMenu) {
                                        // Itera sobre cada um dos links e adiciona o evento de clique
                                        linksMenu.forEach( (link) => {
                                                link.addEventListener("click", (event) => {
                                                        // Desabilita o link ao ser clicado
                                                        event.preventDefault();
                                                        disableLink(link);

                                                        // Reativa o link após a navegação/saída da página
                                                        window.addEventListener('beforeunload', () => {
                                                                link.disabled = false;
                                                        });

                                                        window.location.href = link.href;
                                                });
                                        });
                                }

                                addClickEventLinkMenu(linksMenu);

                                let observer = new MutationObserver((mutationsList) => {
                                        linksMenu = retornaLinksMenu();
                                        for (var mutation of mutationsList) {
                                                if (mutation.type === 'childList') {
                                                        addClickEventLinkMenu(linksMenu); // Aplica os eventos de click nos novos elementos
                                                }
                                        }
                                });

                                observer.observe(document.body, { childList: true, subtree: true });

                                function disableLink(linkElement) {
                                        linkElement.style.pointerEvents = "none"; // Desabilita os cliques no link
                                        linkElement.style.opacity = "0.5"; // Opcional: muda a aparência para indicar que está desabilitado
                                }

                                function retornaLinksMenu() {
                                        return document.querySelectorAll("#menu_principal li a");
                                }
                        })

                //

div.script:
