        function fecharPainelErros() {
                var iterator = document.evaluate("//div[@id='painel-erros']", document,null, XPathResult.UNORDERED_NODE_ITERATOR_TYPE, null);
                var thisNode = iterator.iterateNext();

                while (thisNode) {
                        thisNode.style.display = 'none';
                        thisNode = iterator.iterateNext();
                }
        }
