        PainelNoticias.init('/sigeduc/geral/noticia/viewNoticia.jsf');
        var J = jQuery.noConflict();
        J(document).ready(function() {

                function getElementByXpath(path) {
                          return document.evaluate(path, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
                }

                getElementByXpath("//td[@class='ThemeOfficeMenuItemText'][contains(text(), 'Boletim')]/..").addEventListener("click", function(){
                    show_carregando();
                }, false);
